permissionDenials.command:
node --input-type=module -e "
import { supportRefundAllowed } from './support.mjs';
import { appRefundAllowed } from './app.mjs';
const day = 864e5;
const order = { tenantId: 'tenant-demo', status: 'PAID', paidAt: 0 };
const attacker = { tenantId: 'other-tenant' };
const t = (f, o, a, n) => { try { return f(o, a, n); } catch (e) { return 'THROW:' + e.message; } };
const cases = [
  ['support cross-tenant @ day1', () => t(supportRefundAllowed, order, attacker, day)],
  ['app     cross-tenant @ day1', () => t(appRefundAllowed, order, attacker, day)],
  ['support @ 7d (boundary)', () => t(supportRefundAllowed, order, {tenantId:'tenant-demo'}, 7*day)],
  ['support @ 7d+1ms', () => t(supportRefundAllowed, order, {tenantId:'tenant-demo'}, 7*day+1)],
  ['support @ 14d (policy boundary)', () => t(supportRefundAllowed, order, {tenantId:'tenant-demo'}, 14*day)],
  ['support @ 14d+1ms', () => t(supportRefundAllowed, order, {tenantId:'tenant-demo'}, 14*day+1)],
  ['support @ -1ms', () => t(supportRefundAllowed, order, {tenantId:'tenant-demo'}, -1)],
  ['support REFUNDED @ day1', () => t(supportRefundAllowed, {...order,status:'REFUNDED'}, {tenantId:'tenant-demo'}, day)],
  ['support missing actor', () => t(supportRefundAllowed, order, undefined, day)],
];
for (const [n, f] of cases) console.log(n.padEnd(38), '=>', f());
"
